function isPlainObject(v: any): v is Record<string, unknown> {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function deepEqual(a: any, b: any): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}

function mergeArrays(a: any[], b: any[]): any[] {
  const result: any[] = [...a];
  for (const item of b) {
    if (!result.some(existing => deepEqual(existing, item))) {
      result.push(item);
    }
  }
  return result;
}

function deepMerge(a: any, b: any): any {
  if (Array.isArray(a) && Array.isArray(b)) {
    return mergeArrays(a, b);
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: Record<string, unknown> = { ...a };
    for (const [key, bVal] of Object.entries(b)) {
      if (key in result) {
        result[key] = deepMerge(result[key], bVal);
      } else {
        result[key] = bVal;
      }
    }
    return result;
  }
  // scalar conflict or type mismatch: B wins
  return b;
}

function sortKeys(value: any): any {
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }
  if (isPlainObject(value)) {
    const sorted: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) {
      sorted[key] = sortKeys(value[key]);
    }
    return sorted;
  }
  return value;
}

