def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        keys = set(a.keys()) | set(b.keys())
        for k in keys:
            if k in a and k in b:
                result[k] = deep_merge(a[k], b[k])
            elif k in a:
                result[k] = a[k]
            else:
                result[k] = b[k]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = list(a)
        for item in b:
            if item not in result:
                result.append(item)
        return result
    else:
