import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.text.DecimalFormat;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String path = "/tmp/…/employees.csv";
        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        double totalBudget = 0;
        String highestName = "";
        double highestSalary = -1;

        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line = br.readLine(); // header
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                String[] parts = line.split(",", -1);
                if (parts.length < 6) continue;
                String name = parts[1].trim();
                String department = parts[2].trim();
                double salary = Double.parseDouble(parts[3].trim());

                deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
                deptCount.put(department, deptCount.getOrDefault(department, 0) + 1);

                totalBudget += salary;
                if (salary > highestSalary) {
                    highestSalary = salary;
                    highestName = name;
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
            return;
        }

        DecimalFormat fmtAvg = new DecimalFormat("#,##0.00");
        DecimalFormat fmtInt = new DecimalFormat("#,##0");

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> e : deptSalaries.entrySet()) {
            String dept = e.getKey();
            List<Double> salaries = e.getValue();
            double sum = 0;
            for (double s : salaries) sum += s;
            double avg = sum / salaries.size();
            System.out.println("  " + dept + ": $" + fmtAvg.format(avg));
        }
        System.out.println();
        System.out.println("Highest Paid: " + highestName + " ($" + fmtInt.format(highestSalary) + ")");
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> e : deptCount.entrySet()) {
            if (e.getValue() > 2) {
                System.out.println("  " + e.getKey() + " (" + e.getValue() + " employees)");
            }
        }
        System.out.println();
        System.out.println("Total Budget: $" + fmtInt.format(totalBudget));
    }
}

