use std::collections::HashMap;
use std::fs;

fn format_int_with_commas(n: i64) -> String {
    let sign = if n < 0 { "-" } else { "" };
    let s = n.abs().to_string();
    let mut chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    if len <= 3 {
        return format!("{}{}", sign, s);
    }
    let mut out = String::new();
    let mut count = 0;
    for c in chars.iter().rev() {
        if count > 0 && count % 3 == 0 {
            out.push(',');
        }
        out.push(*c);
        count += 1;
    }
    let rev: String = out.chars().rev().collect();
    format!("{}{}", sign, rev)
}

fn comma_format_int_str(s: &str) -> String {
    let s = s.trim_start_matches('-');
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    if len <= 3 {
        return s.to_string();
    }
    let mut out = String::new();
    let mut count = 0;
    for c in chars.iter().rev() {
        if count > 0 && count % 3 == 0 {
            out.push(',');
        }
        out.push(*c);
        count += 1;
    }
    out.chars().rev().collect()
}

fn format_money_average(value: f64) -> String {
    let s = format!("{:.2}", value);
    let mut parts = s.split('.');
    let int_part = parts.next().unwrap_or("0");
    let frac_part = parts.next().unwrap_or("00");
    let int_comma = comma_format_int_str(int_part);
    format!("${}.{}", int_comma, frac_part)
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let content = fs::read_to_string(path).expect("failed to read csv");
    let mut lines = content.lines();

    let header = lines.next().unwrap_or("");
    let headers: Vec<&str> = header.split(',').map(|h| h.trim()).collect();
    let idx_name = headers.iter().position(|h| *h == "name").unwrap_or(1);
    let idx_dept = headers.iter().position(|h| *h == "department").unwrap_or(2);
    let idx_salary = headers.iter().position(|h| *h == "salary").unwrap_or(3);

    let mut dept_sum: HashMap<String, f64> = HashMap::new();
    let mut dept_cnt: HashMap<String, usize> = HashMap::new();
    let mut total_budget: i64 = 0;
    let mut highest_salary: i64 = i64::MIN;
    let mut highest_name = String::new();

    for line in lines {
        let line = line.trim();
        if line.is_empty() { continue; }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() <= idx_salary { continue; }
        let name = fields[idx_name].trim().to_string();
        let dept = fields[idx_dept].trim().to_string();
        let salary_str = fields[idx_salary].trim();
        let salary: i64 = match salary_str.parse() {
            Ok(v) => v,
            Err(_) => continue,
        };
        *dept_sum.entry(dept.clone()).or_insert(0.0) += salary as f64;
        *dept_cnt.entry(dept.clone()).or_insert(0) += 1;
        total_budget += salary;
        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    let mut depts: Vec<String> = dept_sum.keys().cloned().collect();
    depts.sort();

    println!("=== Salary Report ===\n");
    println!("Average Salary by Department:");
    for dept in &depts {
        let sum = dept_sum.get(dept).unwrap_or(&0.0);
        let cnt = *dept_cnt.get(dept).unwrap_or(&1) as f64;
        let avg = sum / cnt;
        println!("  {}: {}", dept, format_money_average(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_int_with_commas(highest_salary));
    println!();
    println!("Departments with >2 employees:");
    let mut depts_gt2: Vec<(&String, usize)> = dept_cnt.iter()
        .filter(|(_, &c)| c > 2)
        .map(|(d, &c)| (d, c))
        .collect();
    depts_gt2.sort_by_key(|(d, _)| d.clone());
    for (dept, cnt) in depts_gt2 {
        println!("  {} ({} employees)", dept, cnt);
    }
    println!();
    println!("Total Budget: ${}", format_int_with_commas(total_budget));
}

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Product {
        String name;
        double price;
        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("http://127.0.0.1:18923/api/products"))
                .GET()
                .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        String json = response.body();

        List<Product> products = new ArrayList<>();
        Pattern objPattern = Pattern.compile("\\{[^}]*\\}");
        Matcher objMatcher = objPattern.matcher(json);
        Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]+)\"");
        Pattern pricePattern = Pattern.compile("\"price\"\\s*:\\s*([0-9]+(?:\\.[0-9]+)?)");
        while (objMatcher.find()) {
            String obj = objMatcher.group();
            Matcher nameMatcher = namePattern.matcher(obj);
            Matcher priceMatcher = pricePattern.matcher(obj);
            if (nameMatcher.find() && priceMatcher.find()) {
                String name = nameMatcher.group(1);
                double price = Double.parseDouble(priceMatcher.group(1));
                products.add(new Product(name, price));
            }
        }

        List<Product> filtered = new ArrayList<>();
        for (Product p : products) {
            if (p.price > 50.00) {
                filtered.add(p);
            }
        }
        Collections.sort(filtered, (a, b) -> a.name.compareToIgnoreCase(b.name));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
