with open(FILE_PATH, "r") as f:
    data = json.load(f)

nodes_set = set(data.get("nodes", []))
adj = {}

for n in nodes_set:
    adj[n] = []

for e in data.get("edges", []):
    u = e["from"]
    v = e["to"]
    w = e["weight"]
    nodes_set.add(u)
    nodes_set.add(v)
    if u not in adj:
        adj[u] = []
    if v not in adj:
        adj[v] = []
    adj[u].append((v, w))
    adj[v].append((u, w))

nodes = list(nodes_set)
if START not in adj:
    adj[START] = []
    nodes.append(START)

dist = {n: float("inf") for n in nodes}
dist[START] = 0
heap = [(0, START)]
visited = set()

while heap:
    d, u = heapq.heappop(heap)
    if u in visited:
        continue
    visited.add(u)
    for v, w in adj.get(u, []):
        nd = d + w
        if nd < dist.get(v, float("inf")):
            dist[v] = nd
            heapq.heappush(heap, (nd, v))

