#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char *name;
    double sum;
    int count;
} Dept;

void format_int_commas(long long value, char *out, size_t outsize) {
    char tmp[64];
    int neg = value < 0;
    unsigned long long v = neg ? (unsigned long long)(-value) : (unsigned long long)value;
    snprintf(tmp, sizeof(tmp), "%llu", v);
    int len = strlen(tmp);
    int commas = (len > 0) ? (len - 1) / 3 : 0;
    int outlen = len + commas + (neg ? 1 : 0);
    if (outlen >= (int)outsize) outlen = outsize - 1;
    out[outlen] = '\0';
    int i = len - 1, j = outlen - 1;
    int c = 0;
    while (i >= 0) {
        out[j--] = tmp[i--];
        c++;
        if (c == 3 && i >= 0) {
            out[j--] = ',';
            c = 0;
        }
    }
    if (neg) out[0] = '-';
}

int dept_cmp(const void *a, const void *b) {
    const Dept *da = (const Dept *)a;
    const Dept *db = (const Dept *)b;
    return strcmp(da->name, db->name);
}

int main(void) {
    const char *path = "/tmp/…/employees.csv";
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    char line[1024];
    fgets(line, sizeof(line), f); /* header */

    Dept *depts = NULL;
    size_t dept_cap = 0, dept_n = 0;
    long long total_budget = 0;
    long long best_salary = -1;
    char *best_name = NULL;

    while (fgets(line, sizeof(line), f)) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;

        char *tok;
        char *saveptr;
        tok = strtok_r(line, ",", &saveptr); /* employee_id */
        if (!tok) continue;
        char *employee_id = tok;

        tok = strtok_r(NULL, ",", &saveptr); /* name */
        if (!tok) continue;
        char *name = tok;

        tok = strtok_r(NULL, ",", &saveptr); /* department */
        if (!tok) continue;
        char *department = tok;

        tok = strtok_r(NULL, ",", &saveptr); /* salary */
        if (!tok) continue;
        long long salary = strtoll(tok, NULL, 10);

        /* start_date and rating ignored */
        /* strtok_r for remaining fields to keep parsing simple */
        /* strtok_r(NULL, ",", &saveptr); start_date */
        /* strtok_r(NULL, ",", &saveptr); rating */

        total_budget += salary;

        if (salary > best_salary) {
            best_salary = salary;
            free(best_name);
            best_name = strdup(name);
        }

        /* find department */
        int idx = -1;
        for (size_t i = 0; i < dept_n; i++) {
            if (strcmp(depts[i].name, department) == 0) { idx = (int)i; break; }
        }
        if (idx == -1) {
            if (dept_n == dept_cap) {
                size_t newcap = dept_cap ? dept_cap * 2 : 8;
                Dept *tmp = realloc(depts, newcap * sizeof(Dept));
                if (!tmp) { fclose(f); return 1; }
                depts = tmp;
                dept_cap = newcap;
            }
            depts[dept_n].name = strdup(department);
            depts[dept_n].sum = 0;
            depts[dept_n].count = 0;
            idx = (int)dept_n;
            dept_n++;
        }
        depts[idx].sum += salary;
        depts[idx].count += 1;
    }
    fclose(f);

    qsort(depts, dept_n, sizeof(Dept), dept_cmp);

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");
    char buf[128];
    for (size_t i = 0; i < dept_n; i++) {
        double avg = depts[i].sum / depts[i].count;
        long long cents = llround(avg * 100.0);
        long long int_part = cents / 100;
        long long frac = llabs(cents % 100);
        char intbuf[64];
        format_int_commas(int_part, intbuf, sizeof(intbuf));
        snprintf(buf, sizeof(buf), "%s.%02lld", intbuf, frac);
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");

    char bestbuf[64];
    format_int_commas(best_salary, bestbuf, sizeof(bestbuf));
    printf("Highest Paid: %s ($%s)\n", best_name ? best_name : "", bestbuf);
    printf("\n");

    printf("Departments with >2 employees:\n");
    for (size_t i = 0; i < dept_n; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");

    char totalbuf[64];
    format_int_commas(total_budget, totalbuf, sizeof(totalbuf));
    printf("Total Budget: $%s\n", totalbuf);

    for (size_t i = 0; i < dept_n; i++) free(depts[i].name);
    free(depts);
    free(best_name);
    return 0;
}

use std::collections::{HashMap, HashSet};
use std::fs::read_to_string;

fn main() {
    let path = "/tmp/…/app.log";
    let content = read_to_string(path).unwrap_or_default();

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut component_error_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: HashSet<String> = HashSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if !line.starts_with('[') {
            continue;
        }
        if let Some(close_idx) = line.find(']') {
            let timestamp = &line[1..close_idx];
            let after = line[close_idx + 1..].trim();
            let mut split = after.splitn(2, ' ');
            let level = split.next().unwrap_or("").to_string();
            let rest2 = split.next().unwrap_or("").trim();
            if rest2.is_empty() {
                continue;
            }
            if let Some(lparen) = rest2.find('(') {
                if let Some(rparen_rel) = rest2[lparen..].find(')') {
                    let rparen = lparen + rparen_rel;
                    let component = &rest2[lparen + 1..rparen];
                    let after_comp = rest2[rparen + 1..].trim_start();
                    let message = if after_comp.starts_with('-') {
                        after_comp[1..].trim_start().to_string()
                    } else {
                        String::new()
                    };

                    // level count
                    *level_counts.entry(level.clone()).or_insert(0) += 1;

                    // hour count
                    if let Some(space) = timestamp.find(' ') {
                        let time_part = &timestamp[space + 1..];
                        if time_part.len() >= 2 {
                            let hour = &time_part[0..2];
                            *hour_counts.entry(hour.to_string()).or_insert(0) += 1;
                        }
                    }

                    // error specific
                    if level == "ERROR" {
                        *component_error_counts.entry(component.to_string()).or_insert(0) += 1;
                        if !message.is_empty() {
                            error_messages.insert(message);
                        }
                    }
                }
            }
        }
    }

    println!("=== Log Analysis ===\n");
    println!("Entries by Level:");
    let mut levels: Vec<_> = level_counts.iter().collect();
    levels.sort_by_key(|(k, _)| k.clone());
    for (lvl, cnt) in levels {
        println!("  {}: {}", lvl, cnt);
    }
    println!();

    let (most_component, most_errors) = if component_error_counts.is_empty() {
        ("None".to_string(), 0)
    } else {
        component_error_counts.iter().max_by_key(|(_, v)| *v).map(|(k, v)| (k.clone(), *v)).unwrap()
    };
    println!("Component with Most Errors: {} ({} errors)", most_component, most_errors);
    println!();

    println!("Unique Error Messages:");
    let mut msgs: Vec<_> = error_messages.into_iter().collect();
    msgs.sort();
    for msg in msgs {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = if hour_counts.is_empty() {
        ("00".to_string(), 0)
    } else {
        hour_counts.iter().max_by(|a, b| a.1.cmp(b.1).then_with(|| a.0.cmp(&b.0))).map(|(k, v)| (k.clone(), *v)).unwrap()
    };
    println!("Busiest Hour: {}:00 ({} entries)", busiest_hour, busiest_count);
}

import * as fs from 'fs';

const filePath = '/tmp/…/graph.json';
const raw = fs.readFileSync(filePath, 'utf8');
const graph = JSON.parse(raw);

const nodes: string[] = graph.nodes || [];
const edges: { from: string; to: string; weight: number }[] = graph.edges || [];

const adj = new Map<string, { node: string; weight: number }[]>();
for (const n of nodes) {
  adj.set(n, []);
}
for (const e of edges) {
  if (!adj.has(e.from)) adj.set(e.from, []);
  if (!adj.has(e.to)) adj.set(e.to, []);
  adj.get(e.from)!.push({ node: e.to, weight: e.weight });
  adj.get(e.to)!.push({ node: e.from, weight: e.weight });
}

const start = 'A';
const dist = new Map<string, number>();
for (const n of nodes) {
  dist.set(n, Infinity);
}
dist.set(start, 0);

const unvisited = new Set<string>(nodes);

while (unvisited.size > 0) {
  let u: string | null = null;
  let minDist = Infinity;
  for (const node of unvisited) {
    const d = dist.get(node)!;
    if (d < minDist) {
      minDist = d;
      u = node;
    }
  }
  if (u === null || minDist === Infinity) break;
  unvisited.delete(u);
  const neighbors = adj.get(u) || [];
  for (const { node: v, weight } of neighbors) {
    if (!dist.has(v)) continue;
    const alt = dist.get(u)! + weight;
    if (alt < dist.get(v)!) {
      dist.set(v, alt);
    }
  }
}

const sortedNodes = [...nodes].sort();
console.log('=== Shortest Paths from A ===');
console.log('');
for (const n of sortedNodes) {
  const d = dist.get(n);
  const out = d === Infinity ? 'Infinity' : d.toString();
  console.log(`A -> ${n}: ${out}`);
}

import Foundation

struct Graph: Codable {
    let nodes: [String]
    let edges: [Edge]
}
struct Edge: Codable {
    let from: String
    let to: String
    let weight: Int
}

let path = "/tmp/…/graph.json"
let data = try Data(contentsOf: URL(fileURLWithPath: path))
let graph = try JSONDecoder().decode(Graph.self, from: data)

var adj = [String: [(String, Int)]]()
for n in graph.nodes {
    adj[n] = []
}
for e in graph.edges {
    adj[e.from, default: []].append((e.to, e.weight))
    adj[e.to, default: []].append((e.from, e.weight))
}

let source = "A"
var dist = [String: Int]()
for n in graph.nodes {
    dist[n] = Int.max
}
dist[source] = 0
var visited = Set<String>()

while visited.count < graph.nodes.count {
    var u: String? = nil
    var best = Int.max
    for n in graph.nodes where !visited.contains(n) {
        if let d = dist[n], d < best {
            best = d
            u = n
        }
    }
    guard let current = u, best != Int.max else { break }
    visited.insert(current)
    guard let neighbors = adj[current] else { continue }
    for (v, w) in neighbors {
        if visited.contains(v) { continue }
        let alt = best + w
        if alt < (dist[v] ?? Int.max) {
            dist[v] = alt
        }
    }
}

print("=== Shortest Paths from A ===")
print("")
let sortedNodes = graph.nodes.sorted()
for n in sortedNodes {
    let d = dist[n] ?? Int.max
    let ds = d == Int.max ? "unreachable" : String(d)
    print("A -> \(n): \(ds)")
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Edge {
        String to;
        long weight;
        Edge(String to, long weight) { this.to = to; this.weight = weight; }
    }

    static class NodeDist implements Comparable<NodeDist> {
        String node;
        long dist;
        NodeDist(String node, long dist) { this.node = node; this.dist = dist; }
        public int compareTo(NodeDist o) { return Long.compare(this.dist, o.dist); }
    }

    public static void main(String[] args) throws IOException {
        String path = "/tmp/…/graph.json";
        String content = Files.readString(Paths.get(path));

        Set<String> nodesSet = new LinkedHashSet<>();
        Pattern nodesPat = Pattern.compile("\"nodes\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher nodesMatcher = nodesPat.matcher(content);
        if (nodesMatcher.find()) {
            String nodesList = nodesMatcher.group(1);
            Pattern itemPat = Pattern.compile("\"([^\"]+)\"");
            Matcher itemMatcher = itemPat.matcher(nodesList);
            while (itemMatcher.find()) {
                nodesSet.add(itemMatcher.group(1));
            }
        }

        Map<String, List<Edge>> adj = new HashMap<>();
        Pattern edgePat = Pattern.compile("\\{\\s*\"from\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"to\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"weight\"\\s*:\\s*(\\d+)\\s*\\}");
        Matcher edgeMatcher = edgePat.matcher(content);
        while (edgeMatcher.find()) {
            String from = edgeMatcher.group(1);
            String to = edgeMatcher.group(2);
            long w = Long.parseLong(edgeMatcher.group(3));
            nodesSet.add(from);
            nodesSet.add(to);
            adj.computeIfAbsent(from, k -> new ArrayList<>()).add(new Edge(to, w));
            adj.computeIfAbsent(to, k -> new ArrayList<>()).add(new Edge(from, w));
        }
        for (String n : nodesSet) adj.computeIfAbsent(n, k -> new ArrayList<>());

        String source = "A";
        Map<String, Long> dist = new HashMap<>();
        for (String n : nodesSet) dist.put(n, Long.MAX_VALUE);
        if (dist.containsKey(source)) dist.put(source, 0L);

        PriorityQueue<NodeDist> pq = new PriorityQueue<>();
        pq.offer(new NodeDist(source, 0));
        Set<String> visited = new HashSet<>();
        while (!pq.isEmpty()) {
            NodeDist cur = pq.poll();
            if (visited.contains(cur.node)) continue;
            visited.add(cur.node);
            for (Edge e : adj.getOrDefault(cur.node, Collections.emptyList())) {
                long nd = cur.dist + e.weight;
                if (nd < dist.getOrDefault(e.to, Long.MAX_VALUE)) {
                    dist.put(e.to, nd);
                    pq.offer(new NodeDist(e.to, nd));
                }
            }
        }

        List<String> sortedNodes = new ArrayList<>(nodesSet);
        Collections.sort(sortedNodes);

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : sortedNodes) {
            long d = dist.getOrDefault(n, Long.MAX_VALUE);
            if (d == Long.MAX_VALUE) d = -1;
            System.out.println("A -> " + n + ": " + d);
        }
    }
}

