char *find_field(const char *obj_start, const char *obj_end, const char *field) {
    size_t field_len = strlen(field);
    const char *p = obj_start;
    while (p && p < obj_end) {
        p = strstr(p, field);
        if (!p || p >= obj_end) return NULL;
        p += field_len;
        while (p < obj_end && (*p == ':' || *p == ' ' || *p == '\t' || *p == '\r' || *p == '\n')) p++;
        if (p >= obj_end) return NULL;
        return (char *)p;
    }
    return NULL;
}

int extract_name(const char *obj_start, const char *obj_end, char *out_name) {
    const char *p = find_field(obj_start, obj_end, "\"name\"");
    if (!p) return 0;
    if (*p != '"') return 0;
    p++;
    const char *q = p;
    while (q < obj_end && *q != '"') q++;
    if (q >= obj_end) return 0;
    size_t len = q - p;
    if (len >= MAX_NAME) len = MAX_NAME - 1;
    memcpy(out_name, p, len);
    out_name[len] = '\0';
    return 1;
}

