import * as fs from 'fs';
import * as path from 'path';

const baseDir = '/tmp/…/project_tree';

type FileInfo = {
  relPath: string;
  lines: number;
  chars: number;
};

const extMap = new Map<string, FileInfo[]>();
let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

function countLinesAndChars(filePath: string): { lines: number; chars: number } {
  const stat = fs.statSync(filePath);
  const size = stat.size;
  const buf = fs.readFileSync(filePath);
  let lines = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 0x0a) lines++;
  }
  if (size > 0 && buf[buf.length - 1] !== 0x0a) {
    lines += 1;
  }
  if (size === 0) lines = 0;
  return { lines, chars: size };
}

function walk(currentAbs: string, relBase: string) {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(currentAbs, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.name === '.' || entry.name === '..') continue;
    const absPath = path.join(currentAbs, entry.name);
    const relPath = path.posix.join(relBase, entry.name);
    let stats: fs.Stats;
    try {
      stats = fs.lstatSync(absPath);
    } catch {
      continue;
    }
    if (stats.isSymbolicLink()) continue;
    if (stats.isDirectory()) {
      walk(absPath, relPath);
    } else if (stats.isFile()) {
      const { lines, chars } = countLinesAndChars(absPath);
      const ext = path.extname(entry.name) || '';
      const info: FileInfo = { relPath, lines, chars };
      if (!extMap.has(ext)) extMap.set(ext, []);
      extMap.get(ext)!.push(info);
      totalFiles++;
      totalLines += lines;
      totalChars += chars;
    }
  }
}

