import Foundation

let pathA = "/tmp/…/config_a.json"
let pathB = "/tmp/…/config_b.json"

func readJSON(at path: String) -> Any? {
    guard let data = FileManager.default.contents(atPath: path) else { return nil }
    return try? JSONSerialization.jsonObject(with: data, options: [])
}

func valuesEqual(_ lhs: Any, _ rhs: Any) -> Bool {
    if let lData = try? JSONSerialization.data(withJSONObject: lhs, options: []),
       let rData = try? JSONSerialization.data(withJSONObject: rhs, options: []) {
        return lData == rData
    }
    return "\(lhs)" == "\(rhs)"
}

func containsEqual(_ array: [Any], _ value: Any) -> Bool {
    for item in array {
        if valuesEqual(item, value) { return true }
    }
    return false
}

func merge(_ a: Any?, _ b: Any?) -> Any? {
    guard let bVal = b else { return a }
    guard let aVal = a else { return bVal }

    if let aDict = aVal as? [String: Any], let bDict = bVal as? [String: Any] {
        var result = aDict
        for (k, bV) in bDict {
            if let aV = result[k] {
                result[k] = merge(aV, bV)
            } else {
                result[k] = bV
            }
        }
        return result
    }

    if let aArr = aVal as? [Any], let bArr = bVal as? [Any] {
        var result = aArr
        for item in bArr {
            if !containsEqual(result, item) {
                result.append(item)
            }
        }
        return result
    }

    return bVal
}

func sortKeys(_ obj: Any) -> Any {
    if let dict = obj as? [String: Any] {
        var newDict: [String: Any] = [:]
        for k in dict.keys.sorted() {
            newDict[k] = sortKeys(dict[k]!)
        }
        return newDict
    } else if let arr = obj as? [Any] {
        return arr.map { sortKeys($0) }
    } else {
        return obj
    }
}

