public class Main {
    public static void main(String[] args) {
        int[][] A = {{1,2,3},{4,5,6},{7,8,9}};
        int[][] B = {{9,8,7},{6,5,4},{3,2,1}};
        int[][] C = multiply(A, B);
        int det = determinant(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + det);
    }

    private static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int m = B[0].length;
        int p = A[0].length;
        int[][] C = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int sum = 0;
                for (int k = 0; k < p; k++) {
                    sum += A[i][k] * B[k][j];
                }
                C[i][j] = sum;
            }
        }
        return C;
    }

    private static int determinant(int[][] M) {
        int a = M[0][0];
        int b = M[0][1];
        int c = M[0][2];
        int d = M[1][0];
        int e = M[1][1];
        int f = M[1][2];
        int g = M[2][0];
        int h = M[2][1];
        int i = M[2][2];
        return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
    }

    private static void printMatrix(int[][] M) {
        for (int i = 0; i < M.length; i++) {
            System.out.print("  ");
            for (int j = 0; j < M[i].length; j++) {
                System.out.printf("%4d", M[i][j]);
                if (j < M[i].length - 1) System.out.print(" ");
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    static class FileRecord {
        String relPath;
        long lines;
        long chars;
        FileRecord(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws IOException {
        String baseDir = "/tmp/…/project_tree";
        Path base = Paths.get(baseDir);
        Map<String, List<FileRecord>> byExt = new TreeMap<>();

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        Files.walkFileTree(base, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                if (Files.isSymbolicLink(dir)) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                if (Files.isSymbolicLink(file)) return FileVisitResult.CONTINUE;
                if (!attrs.isRegularFile()) return FileVisitResult.CONTINUE;

                String name = file.getFileName().toString();
                int dot = name.lastIndexOf('.');
                String ext;
                if (dot > 0 && dot < name.length() - 1) {
                    ext = name.substring(dot).toLowerCase();
                } else {
                    ext = "";
                }

                Path rel = base.relativize(file);
                String relPath = rel.toString().replace('\\', '/');

                long chars = Files.size(file);
                long lines = 0;
                try (BufferedReader br = Files.newBufferedReader(file)) {
                    while (br.readLine() != null) lines++;
                } catch (IOException e) {
                    lines = 0;
                }

                FileRecord rec = new FileRecord(relPath, lines, chars);
                byExt.computeIfAbsent(ext, k -> new ArrayList<>()).add(rec);
                totalFiles++;
                totalLines += lines;
                totalChars += chars;
                return FileVisitResult.CONTINUE;
            }
        });

        System.out.println("=== File Tree Analysis ===");
        System.out.println();
        for (Map.Entry<String, List<FileRecord>> e : byExt.entrySet()) {
            String ext = e.getKey();
            List<FileRecord> list = e.getValue();
            list.sort(Comparator.comparing(r -> r.relPath));
            long files = list.size();
            long sumLines = 0;
            long sumChars = 0;
            for (FileRecord r : list) {
                sumLines += r.lines;
                sumChars += r.chars;
            }
            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + files);
            System.out.println("  Total Lines: " + sumLines);
            System.out.println("  Total Characters: " + sumChars);
            for (FileRecord r : list) {
                System.out.println("    " + r.relPath + ": " + r.lines + " lines, " + r.chars + " chars");
            }
        }
        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }
}

