public class Main {
    public static void main(String[] args) throws Exception {
        String pathA = "/tmp/…/config_a.json";
        String pathB = "/tmp/…/config_b.json";
        String aText = java.nio.file.Files.readString(java.nio.file.Path.of(pathA));
        String bText = java.nio.file.Files.readString(java.nio.file.Path.of(pathB));
        Object a = new Parser(aText).parseValue();
        Object b = new Parser(bText).parseValue();
        Object merged = merge(a, b);
        StringBuilder out = new StringBuilder();
        writeValue(merged, out, 0);
        System.out.print(out.toString());
    }

    static Object merge(Object a, Object b) {
        if (a instanceof java.util.Map && b instanceof java.util.Map) {
            java.util.Map<String, Object> ma = (java.util.Map<String, Object>) a;
            java.util.Map<String, Object> mb = (java.util.Map<String, Object>) b;
            java.util.Map<String, Object> res = new java.util.LinkedHashMap<>();
            java.util.Set<String> keys = new java.util.HashSet<>();
            keys.addAll(ma.keySet());
            keys.addAll(mb.keySet());
            for (String k : keys) {
                if (ma.containsKey(k) && mb.containsKey(k)) {
                    res.put(k, merge(ma.get(k), mb.get(k)));
                } else if (ma.containsKey(k)) {
                    res.put(k, ma.get(k));
                } else {
                    res.put(k, mb.get(k));
                }
            }
            return res;
        }
        if (a instanceof java.util.List && b instanceof java.util.List) {
            java.util.List<Object> la = (java.util.List<Object>) a;
            java.util.List<Object> lb = (java.util.List<Object>) b;
            java.util.List<Object> res = new java.util.ArrayList<>();
            for (Object o : la) res.add(o);
            for (Object o : lb) {
                if (!res.contains(o)) res.add(o);
            }
            return res;
        }
        return b;
    }

    static void writeValue(Object v, StringBuilder sb, int level) {
        if (v instanceof java.util.Map) {
            writeObject((java.util.Map<String, Object>) v, sb, level);
        } else if (v instanceof java.util.List) {
            writeArray((java.util.List<Object>) v, sb, level);
        } else {
            writePrimitive(v, sb);
        }
    }

    static void writeObject(java.util.Map<String, Object> map, StringBuilder sb, int level) {
        sb.append("{\n");
        java.util.List<String> keys = new java.util.ArrayList<>(map.keySet());
        java.util.Collections.sort(keys);
        for (int i = 0; i < keys.size(); i++) {
            String k = keys.get(i);
            Object val = map.get(k);
            indent(sb, level + 1);
            writeString(k, sb);
            sb.append(": ");
            if (val instanceof java.util.Map || val instanceof java.util.List) {
                sb.append("\n");
                writeValue(val, sb, level + 1);
            } else {
                writePrimitive(val, sb);
                if (i < keys.size() - 1) sb.append(",");
                sb.append("\n");
            }
        }
        indent(sb, level);
        sb.append("}");
    }

    static void writeArray(java.util.List<Object> list, StringBuilder sb, int level) {
        if (list.isEmpty()) {
            sb.append("[]");
            return;
        }
        sb.append("[\n");
        for (int i = 0; i < list.size(); i++) {
            Object v = list.get(i);
            indent(sb, level + 1);
            if (v instanceof java.util.Map || v instanceof java.util.List) {
                writeValue(v, sb, level + 1);
            } else {
                writePrimitive(v, sb);
            }
            if (i < list.size() - 1) sb.append(",");
            sb.append("\n");
        }
        indent(sb, level);
        sb.append("]");
    }

    static void writePrimitive(Object v, StringBuilder sb) {
        if (v == null) sb.append("null");
        else if (v instanceof Boolean) sb.append(v.toString());
        else if (v instanceof java.math.BigDecimal) sb.append(v.toString());
        else if (v instanceof Number) sb.append(v.toString());
        else if (v instanceof String) writeString((String) v, sb);
        else sb.append(v.toString());
    }

    static void writeString(String s, StringBuilder sb) {
        sb.append('"');
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        sb.append('"');
    }

    static void indent(StringBuilder sb, int level) {
        for (int i = 0; i < level * 2; i++) sb.append(' ');
    }

    static class Parser {
        private final String s;
        private int i = 0;
        Parser(String s) { this.s = s; }
        Object parseValue() { skipWs(); return parseValueInternal(); }
        private Object parseValueInternal() {
            if (i >= s.length()) return null;
            char c = s.charAt(i);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') { i += 4; return Boolean.TRUE; }
            if (c == 'f') { i += 5; return Boolean.FALSE; }
            if (c == 'n') { i += 4; return null; }
            if (c == '-' || Character.isDigit(c)) return parseNumber();
            throw new RuntimeException("Unexpected char " + c);
        }
        private java.util.Map<String, Object> parseObject() {
            i++; // {
            java.util.Map<String, Object> map = new java.util.LinkedHashMap<>();
            skipWs();
            if (i < s.length() && s.charAt(i) == '}') { i++; return map; }
            while (true) {
                skipWs();
                String key = parseString();
                skipWs();
                if (s.charAt(i) != ':') throw new RuntimeException("Expected :");
                i++;
                Object val = parseValueInternal();
                map.put(key, val);
                skipWs();
                if (i >= s.length()) break;
                char c = s.charAt(i);
                if (c == ',') { i++; continue; }
                if (c == '}') { i++; break; }
            }
            return map;
        }
        private java.util.List<Object> parseArray() {
            i++; // [
            java.util.List<Object> list = new java.util.ArrayList<>();
            skipWs();
            if (i < s.length() && s.charAt(i) == ']') { i++; return list; }
            while (true) {
                Object val = parseValueInternal();
                list.add(val);
                skipWs();
                if (i >= s.length()) break;
                char c = s.charAt(i);
                if (c == ',') { i++; continue; }
                if (c == ']') { i++; break; }
            }
            return list;
        }
        private String parseString() {
            i++; // "
            StringBuilder sb = new StringBuilder();
            while (i < s.length()) {
                char c = s.charAt(i++);
                if (c == '"') break;
                if (c == '\\') {
                    if (i >= s.length()) break;
                    char e = s.charAt(i++);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (i + 4 <= s.length()) {
                                String hex = s.substring(i, i + 4);
                                sb.append((char) Integer.parseInt(hex, 16));
                                i += 4;
                            }
                            break;
                        default: sb.append(e);
                    }
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }
        private java.math.BigDecimal parseNumber() {
            int start = i;
            while (i < s.length() && (Character.isDigit(s.charAt(i)) || "-+eE. ".indexOf(s.charAt(i)) >= 0)) {
                if (s.charAt(i) == ' ' || s.charAt(i) == ',') break;
                i++;
            }
            String num = s.substring(start, i).trim();
            return new java.math.BigDecimal(num);
        }
        private void skipWs() {
            while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
        }
    }
}

