typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileEntry;

FileEntry *files = NULL;
size_t file_count = 0;
size_t file_cap = 0;

static char *get_extension(const char *relpath) {
    const char *base = strrchr(relpath, '/');
    base = base ? base + 1 : relpath;
    const char *dot = strrchr(base, '.');
    if (!dot || dot == base) {
        char *e = malloc(1);
        e[0] = '\0';
        return e;
    }
    size_t len = strlen(dot);
    char *e = malloc(len + 1);
    strcpy(e, dot);
    return e;
}

static void add_file(const char *relpath, const char *ext, long lines, long chars) {
    if (file_count == file_cap) {
        size_t new_cap = file_cap ? file_cap * 2 : 256;
        files = realloc(files, new_cap * sizeof(FileEntry));
        file_cap = new_cap;
    }
    files[file_count].relpath = strdup(relpath);
    files[file_count].ext = strdup(ext);
    files[file_count].lines = lines;
    files[file_count].chars = chars;
    file_count++;
}

static void process_file(const char *abs_path, const char *relpath) {
    FILE *f = fopen(abs_path, "rb");
    if (!f) return;
    long lines = 0;
    long chars = 0;
    unsigned char buf[BUFSIZE];
    size_t n;
    while ((n = fread(buf, 1, BUFSIZE, f)) > 0) {
        chars += n;
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') lines++;
        }
    }
    fclose(f);
    char *ext = get_extension(relpath);
    add_file(relpath, ext, lines, chars);
    free(ext);
}

static void walk_dir(const char *abs_path, const char *rel_path) {
    DIR *dir = opendir(abs_path);
    if (!dir) return;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        const char *name = ent->d_name;
        if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0) continue;
        char abs_buf[PATH_MAX];
        char rel_buf[PATH_MAX];
        snprintf(abs_buf, PATH_MAX, "%s/%s", abs_path, name);
        if (rel_path[0] == '\0')
            snprintf(rel_buf, PATH_MAX, "%s", name);
        else
            snprintf(rel_buf, PATH_MAX, "%s/%s", rel_path, name);
        struct stat st;
        if (lstat(abs_buf, &st) != 0) continue;
        if (S_ISLNK(st.st_mode)) continue;
        if (S_ISDIR(st.st_mode)) {
            walk_dir(abs_buf, rel_buf);
        } else if (S_ISREG(st.st_mode)) {
            process_file(abs_buf, rel_buf);
        }
    }
    closedir(dir);
}

static int cmp_entries(const void *a, const void *b) {
    const FileEntry *fa = (const FileEntry *)a;
    const FileEntry *fb = (const FileEntry *)b;
    int c = strcmp(fa->ext, fb->ext);
    if (c != 0) return c;
    return strcmp(fa->relpath, fb->relpath);
}

