use std::collections::BTreeMap;
use std::fs;

#[derive(Clone)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

struct Parser {
    input: Vec<u8>,
    pos: usize,
}
impl Parser {
    fn new(s: String) -> Self {
        Self { input: s.into_bytes(), pos: 0 }
    }
    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }
    fn next(&mut self) -> Option<u8> {
        let c = self.peek();
        if c.is_some() { self.pos += 1; }
        c
    }
    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\n' | b'\r' | b'\t')) {
            self.pos += 1;
        }
    }
    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => {
                let s = self.parse_string()?;
                Ok(Value::String(s))
            }
            Some(b't') => { self.consume_literal(b't', "true")?; Ok(Value::Bool(true)) }
            Some(b'f') => { self.consume_literal(b'f', "false")?; Ok(Value::Bool(false)) }
            Some(b'n') => { self.consume_literal(b'n', "null")?; Ok(Value::Null) }
            Some(c) if c.is_ascii_digit() || c == b'-' => {
                let num = self.parse_number()?;
                Ok(Value::Number(num))
            }
            Some(c) => Err(format!("unexpected char {}", c as char)),
            None => Err("unexpected EOF".to_string()),
        }
    }
    fn consume_literal(&mut self, first: u8, lit: &str) -> Result<(), String> {
        for (i, ch) in lit.bytes().enumerate() {
            let expected = ch;
            let actual = self.input.get(self.pos + i).copied().unwrap_or(0);
            if actual != expected { return Err("literal mismatch".to_string()); }
        }
        self.pos += lit.len();
        Ok(())
    }
    fn parse_string(&mut self) -> Result<String, String> {
        if self.next() != Some(b'"') { return Err("expected '\"'".to_string()); }
        let mut out = String::new();
        while let Some(c) = self.next() {
            match c {
                b'"' => return Ok(out),
                b'\\' => {
                    let esc = self.next().ok_or("bad escape")?;
                    match esc {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\x08'),
                        b'f' => out.push('\x0c'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            let mut hex = [0u8;4];
                            for i in 0..4 { hex[i] = self.next().ok_or("bad \\u")?; }
                            let s = std::str::from_utf8(&hex).map_err(|_| "bad utf8")?;
                            let code = u16::from_str_radix(s, 16).map_err(|_| "bad hex")?;
                            out.push(char::from_u32(code as u32).unwrap_or('?'));
                        }
                        _ => out.push(esc as char),
                    }
                }
                _ => out.push(c as char),
            }
        }
        Err("unterminated string".to_string())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || matches!(c, b'+'|b'-'|b'.'|b'e'|b'E') {
                self.pos += 1;
            } else { break; }
        }
        let s = String::from_utf8(self.input[start..self.pos].to_vec()).map_err(|_| "bad number")?;
        s.parse::<f64>().map_err(|_| "parse number".to_string())
    }
    fn parse_object(&mut self) -> Result<Value, String> {
        self.next(); // {
        let mut map = BTreeMap::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(Value::Object(map)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.next() != Some(b':') { return Err("expected :".to_string()); }
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err("expected , or }".to_string()),
            }
        }
        Ok(Value::Object(map))
    }
    fn parse_array(&mut self) -> Result<Value, String> {
        self.next(); // [
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(Value::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err("expected , or ]".to_string()),
            }
        }
        Ok(Value::Array(arr))
    }
}

fn parse_json(s: String) -> Value {
    let mut p = Parser::new(s);
    p.parse_value().expect("parse error")
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Number(x), Value::Number(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => {
            if x.len() != y.len() { return false; }
            x.iter().zip(y.iter()).all(|(a,b)| values_equal(a,b))
        }
        (Value::Object(x), Value::Object(y)) => {
            if x.len() != y.len() { return false; }
            x.iter().all(|(k,v)| y.get(k).map_or(false, |v2| values_equal(v, v2)))
        }
        _ => false,
    }
}

fn merge_values(a: &Value, b: &Value) -> Value {
    match (a, b) {
        (Value::Object(a_map), Value::Object(b_map)) => {
            let mut merged = a_map.clone();
            for (k, v_b) in b_map {
                if let Some(v_a) = merged.get(k) {
                    let m = merge_values(v_a, v_b);
                    merged.insert(k.clone(), m);
                } else {
                    merged.insert(k.clone(), v_b.clone());
                }
            }
            Value::Object(merged)
        }
        (Value::Array(a_arr), Value::Array(b_arr)) => {
            let mut res = a_arr.clone();
            for item in b_arr {
                if !res.iter().any(|x| values_equal(x, item)) {
                    res.push(item.clone());
                }
            }
            Value::Array(res)
        }
        _ => b.clone(),
    }
}

fn escape_str(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out
}

fn serialize(v: &Value, level: usize) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Value::Number(n) => {
            if n.fract() == 0.0 { format!("{}", *n as i64) } else { format!("{}", n) }
        }
        Value::String(s) => format!("\"{}\"", escape_str(s)),
        Value::Array(arr) => {
            if arr.is_empty() { return "[]".to_string(); }
            let mut s = String::from("[\n");
            for (i, item) in arr.iter().enumerate() {
                s.push_str(&" ".repeat((level + 1) * 2));
                let item_s = serialize(item, level + 1);
                s.push_str(&item_s);
                if i + 1 < arr.len() { s.push(','); }
                s.push('\n');
            }
            s.push_str(&" ".repeat(level * 2));
            s.push(']');
            s
        }
        Value::Object(map) => {
            if map.is_empty() { return "{}".to_string(); }
            let mut s = String::from("{\n");
            for (i, (k, v)) in map.iter().enumerate() {
                s.push_str(&" ".repeat((level + 1) * 2));
                s.push_str(&format!("\"{}\": ", escape_str(k)));
                let val_s = serialize(v, level + 1);
                if val_s.contains('\n') {
                    s.push('\n');
                    s.push_str(&" ".repeat((level + 1) * 2));
                    s.push_str(&val_s);
                } else {
                    s.push_str(&val_s);
                }
                if i + 1 < map.len() { s.push(','); }
                s.push('\n');
            }
            s.push_str(&" ".repeat(level * 2));
            s.push('}');
            s
        }
    }
}

