static json_value* parse_object(const char *s, size_t *p, size_t len){
    (*p)++; // {
    json_value *v=json_new(JSON_OBJECT);
    v->u.obj.pairs=NULL; v->u.obj.len=0; v->u.obj.cap=0;
    skip_ws(s,p,len);
    if(*p < len && s[*p]=='}'){ (*p)++; return v; }
    while(1){
        skip_ws(s,p,len);
        char *key=parse_str(s,p,len);
        skip_ws(s,p,len);
        if(*p<len && s[*p]==':') (*p)++;
        skip_ws(s,p,len);
        json_value *val=parse_value(s,p,len);
        // add pair
        if(v->u.obj.len>=v->u.obj.cap){
            v->u.obj.cap = v->u.obj.cap? v->u.obj.cap*2:8;
            v->u.obj.pairs = realloc(v->u.obj.pairs, v->u.obj.cap*sizeof(json_pair));
        }
        v->u.obj.pairs[v->u.obj.len].key=key;
        v->u.obj.pairs[v->u.obj.len].val=val;
        v->u.obj.len++;
        skip_ws(s,p,len);
        if(*p<len && s[*p]==','){ (*p)++; continue; }
        if(*p<len && s[*p]=='}'){ (*p)++; break; }
        break;
    }
    return v;
}

static json_value* parse_array(const char *s, size_t *p, size_t len){
    (*p)++; // [
    json_value *v=json_new(JSON_ARRAY);
    v->u.arr.items=NULL; v->u.arr.len=0; v->u.arr.cap=0;
    skip_ws(s,p,len);
    if(*p < len && s[*p]==']'){ (*p)++; return v; }
    while(1){
        json_value *item=parse_value(s,p,len);
        if(v->u.arr.len>=v->u.arr.cap){
            v->u.arr.cap = v->u.arr.cap? v->u.arr.cap*2:8;
            v->u.arr.items = realloc(v->u.arr.items, v->u.arr.cap*sizeof(json_value*));
        }
        v->u.arr.items[v->u.arr.len++]=item;
        skip_ws(s,p,len);
        if(*p<len && s[*p]==','){ (*p)++; continue; }
        if(*p<len && s[*p]==']'){ (*p)++; break; }
        break;
