static json_value* parse_value(const char *s, size_t *p, size_t len){
    skip_ws(s,p,len);
    if(*p>=len) return NULL;
    char c=s[*p];
    if(c=='{') return parse_object(s,p,len);
    if(c=='[') return parse_array(s,p,len);
    if(c=='"'){
        char *str=parse_str(s,p,len);
        json_value *v=json_new(JSON_STRING);
        v->u.str=str;
        return v;
    }
    if(c=='t'){
        (*p)+4; json_value *v=json_new(JSON_BOOL); v->u.b=true; return v;
    }
    if(c=='f'){
        (*p)+5; json_value *v=json_new(JSON_BOOL); v->u.b=false; return v;
    }
    if(c=='n'){
        (*p)+4; return json_new(JSON_NULL);
    }
    if(c=='-'||isdigit((unsigned char)c)){
        char *end;
        double num=strtod(s+*p,&end);
        *p = (size_t)(end - s);
        json_value *v=json_new(JSON_NUMBER);
        v->u.num=num;
        return v;
    }
    return NULL;
}

static json_value* json_copy(json_value *v){
    if(!v) return NULL;
    json_value *c=json_new(v->type);
    switch(v->type){
        case JSON_BOOL: c->u.b=v->u.b; break;
        case JSON_NUMBER: c->u.num=v->u.num; break;
        case JSON_STRING: c->u.str=strdup(v->u.str); break;
        case JSON_ARRAY:{
            c->u.arr.len=v->u.arr.len; c->u.arr.cap=v->u.arr.len;
            c->u.arr.items=malloc(sizeof(json_value*)*c->u.arr.cap);
            for(int i=0;i<v->u.arr.len;i++) c->u.arr.items[i]=json_copy(v->u.arr.items[i]);
            break;
        }
        case JSON_OBJECT:{
            c->u.obj.len=v->u.obj.len; c->u.obj.cap=v->u.obj.len;
            c->u.obj.pairs=malloc(sizeof(json_pair)*c->u.obj.cap);
            for(int i=0;i<v->u.obj.len;i++){
                c->u.obj.pairs[i].key=strdup(v->u.obj.pairs[i].key);
                c->u.obj.pairs[i].val=json_copy(v->u.obj.pairs[i].val);
            }
            break;
        }
        default: break;
    }
    return c;
}

static bool json_equal(json_value *a, json_value *b){
    if(a==b) return true;
    if(!a||!b) return false;
    if(a->type!=b->type) return false;
    switch(a->type){
        case JSON_BOOL: return a->u.b==b->u.b;
        case JSON_NUMBER: return a->u.num==b->u.num;
        case JSON_STRING: return strcmp(a->u.str,b->u.str)==0;
        case JSON_ARRAY:{
            if(a->u.arr.len!=b->u.arr.len) return false;
            for(int i=0;i<a->u.arr.len;i++) if(!json_equal(a->u.arr.items[i],b->u.arr.items[i])) return false;
            return true;
        }
        case JSON_OBJECT:{
            if(a->u.obj.len!=b->u.obj.len) return false;
            for(int i=0;i<a->u.obj.len;i++){
                json_value *bv=NULL;
                for(int j=0;j<b->u.obj.len;j++) if(strcmp(a->u.obj.pairs[i].key,b->u.obj.pairs[j].key)==0){ bv=b->u.obj.pairs[j].val; break; }
                if(!bv || !json_equal(a->u.obj.pairs[i].val,bv)) return false;
            }
            return true;
        }
        default: return true;
    }
}

static json_value* json_merge(json_value *a, json_value *b){
    if(!a) return json_copy(b);
    if(!b) return json_copy(a);
    if(a->type!=b->type) return json_copy(b);
    if(a->type==JSON_OBJECT){
        json_value *res=json_new(JSON_OBJECT);
        res->u.obj.pairs=malloc(sizeof(json_pair)* (a->u.obj.len + b->u.obj.len));
        res->u.obj.len=0; res->u.obj.cap=a->u.obj.len+b->u.obj.len;
        for(int i=0;i<a->u.obj.len;i++){
            res->u.obj.pairs[res->u.obj.len].key=strdup(a->u.obj.pairs[i].key);
            res->u.obj.pairs[res->u.obj.len].val=json_copy(a->u.obj.pairs[i].val);
            res->u.obj.len++;
        }
        for(int i=0;i<b->u.obj.len;i++){
            char *k=b->u.obj.pairs[i].key;
            int idx=-1;
            for(int j=0;j<res->u.obj.len;j++) if(strcmp(res->u.obj.pairs[j].key,k)==0){ idx=j; break; }
            if(idx>=0){
                json_value *merged=json_merge(res->u.obj.pairs[idx].val,b->u.obj.pairs[i].val);
                res->u.obj.pairs[idx].val=merged;
            }else{
                res->u.obj.pairs[res->u.obj.len].key=strdup(k);
                res->u.obj.pairs[res->u.obj.len].val=json_copy(b->u.obj.pairs[i].val);
                res->u.obj.len++;
            }
        }
        return res;
    }
    if(a->type==JSON_ARRAY){
        json_value *res=json_new(JSON_ARRAY);
        res->u.arr.cap=a->u.arr.len + b->u.arr.len;
        res->u.arr.items=malloc(sizeof(json_value*)*res->u.arr.cap);
        res->u.arr.len=0;
        for(int i=0;i<a->u.arr.len;i++){ res->u.arr.items[res->u.arr.len++]=json_copy(a->u.arr.items[i]); }
        for(int i=0;i<b->u.arr.len;i++){
            bool exists=false;
            for(int j=0;j<res->u.arr.len;j++) if(json_equal(res->u.arr.items[j],b->u.arr.items[i])){ exists=true; break; }
            if(!exists){ res->u.arr.items[res->u.arr.len++]=json_copy(b->u.arr.items[i]); }
        }
        return res;
    }
    return json_copy(b);
}

