static char *read_file(const char *path, size_t *out_len){
    FILE *f = fopen(path,"rb");
    if(!f) return NULL;
    fseek(f,0,SEEK_END);
    long sz = ftell(f);
    fseek(f,0,SEEK_SET);
    char *buf = malloc(sz+1);
    if(!buf){ fclose(f); return NULL; }
    size_t r = fread(buf,1,sz,f);
    buf[r]='\0';
    fclose(f);
    if(out_len) *out_len = r;
    return buf;
}

static void skip_ws(const char *s, size_t *p, size_t len){
    while(*p < len && isspace((unsigned char)s[*p])) (*p)++;
}

static char *parse_str(const char *s, size_t *p, size_t len){
    if(s[*p]!='"') return NULL;
    (*p)++;
    size_t cap=64, sz=0;
    char *out=malloc(cap);
    while(*p < len){
        char c=s[*p++];
        if(c=='"') break;
        if(c=='\\'){
            if(*p>=len) break;
            char e=s[*p++];
            switch(e){
                case '"': c='"'; break;
                case '\\': c='\\'; break;
                case '/': c='/'; break;
                case 'b': c='\b'; break;
                case 'f': c='\f'; break;
                case 'n': c='\n'; break;
                case 'r': c='\r'; break;
                case 't': c='\t'; break;
                default: c=e; break;
            }
        }
        if(sz+1>=cap){ cap*=2; out=realloc(out,cap); }
        out[sz++]=c;
    }
    out[sz]='\0';
    return out;
}

