static void json_print_object(json_value *v, int indent){
    putchar('{');
    if(v->u.obj.len==0){ putchar('\n'); print_indent(indent); putchar('}'); return; }
    putchar('\n');
    json_pair **keys=malloc(sizeof(json_pair*)*v->u.obj.len);
    for(int i=0;i<v->u.obj.len;i++) keys[i]=&v->u.obj.pairs[i];
    for(int i=1;i<v->u.obj.len;i++){
        json_pair *tmp=keys[i];
        int j=i-1;
        while(j>=0 && strcmp(keys[j]->key, tmp->key)>0){ keys[j+1]=keys[j]; j--; }
        keys[j+1]=tmp;
    }
    for(int i=0;i<v->u.obj.len;i++){
        print_indent(indent+2);
        printf("\"%s\": ", keys[i]->key);
        json_print_value(keys[i]->val, indent+2);
        if(i < v->u.obj.len-1) putchar(',');
        putchar('\n');
    }
    free(keys);
    print_indent(indent);
    putchar('}');
}
static void json_print_array(json_value *v, int indent){
    putchar('[');
    if(v->u.arr.len==0){ putchar('\n'); print_indent(indent); putchar(']'); return; }
    putchar('\n');
    for(int i=0;i<v->u.arr.len;i++){
        print_indent(indent+2);
        json_print_value(v->u.arr.items[i], indent+2);
        if(i < v->u.arr.len-1) putchar(',');
        putchar('\n');
    }
    print_indent(indent);
    putchar(']');
}
static void json_print_value(json_value *v, int indent){
    if(!v){ printf("null"); return; }
    switch(v->type){
        case JSON_NULL: printf("null"); break;
        case JSON_BOOL: printf(v->u.b?"true":"false"); break;
        case JSON_NUMBER: printf("%.15g", v->u.num); break;
        case JSON_STRING: printf("\"%s\"", v->u.str); break;
        case JSON_ARRAY: json_print_array(v, indent); break;
        case JSON_OBJECT: json_print_object(v, indent); break;
    }
}

