use std::collections::HashMap;
use std::fs;

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("read file");
    let compact: String = content.chars().filter(|c| !c.is_whitespace()).collect();

    // nodes
    let nodes_start = compact.find("\"nodes\":[").expect("nodes");
    let nodes_end = compact[nodes_start..].find(']').expect("]") + nodes_start;
    let nodes_inner = &compact[nodes_start + 8..nodes_end];
    let mut nodes: Vec<String> = nodes_inner
        .split(',')
        .map(|s| s.trim_matches('"').to_string())
        .filter(|s| !s.is_empty())
        .collect();

    // edges
    let edges_start = compact.find("\"edges\":[").expect("edges");
    let edges_end = compact[edges_start..].find(']').expect("]") + edges_start;
    let edges_inner = &compact[edges_start + 8..edges_end];

    let mut edges = Vec::new();
    let parts: Vec<&str> = edges_inner.split("},{").collect();
    for part in parts {
        let mut obj = part.to_string();
        if !obj.starts_with('{') { obj = format!("{{{obj}"); }
        if !obj.ends_with('}') { obj.push('}'); }
        if let Some(from_idx) = obj.find("\"from\":\"") {
            let from_start = from_idx + 8;
            let from_end = obj[from_start..].find('"').unwrap();
            let from = &obj[from_start..from_start + from_end];
            let to_idx = obj.find("\"to\":\"").unwrap();
            let to_start = to_idx + 6;
            let to_end = obj[to_start..].find('"').unwrap();
            let to = &obj[to_start..to_start + to_end];
            let w_idx = obj.find("\"weight\":").unwrap();
            let w_start = w_idx + 9;
            let w_end = obj[w_start..].find('}').unwrap_or(obj[w_start..].len());
            let w_str = &obj[w_start..w_start + w_end];
            let weight: u32 = w_str.parse().unwrap();
            edges.push((from.to_string(), to.to_string(), weight));
        }
    }

    // adjacency (undirected)
    let mut adj: HashMap<String, Vec<(String, u32)>> = HashMap::new();
    for n in &nodes {
        adj.entry(n.clone()).or_default();
    }
    for (u, v, w) in edges {
        adj.entry(u.clone()).or_default().push((v.clone(), w));
        adj.entry(v.clone()).or_default().push((u.clone(), w));
    }
    // ensure A exists
    if !nodes.contains(&"A".to_string()) {
        nodes.push("A".to_string());
        adj.entry("A".to_string()).or_default();
    }

    // Dijkstra O(V^2)
    let mut dist: HashMap<String, u64> = HashMap::new();
    for n in &nodes {
        dist.insert(n.clone(), u64::MAX);
    }
    *dist.get_mut("A").unwrap() = 0;
    let mut unvisited: Vec<String> = nodes.clone();

    while !unvisited.is_empty() {
        let u = unvisited.iter()
            .min_by_key(|n| dist.get(*n).copied().unwrap_or(u64::MAX))
            .unwrap()
            .clone();
        let du = *dist.get(&u).unwrap();
        if du == u64::MAX { break; }
        unvisited.retain(|x| x != &u);
        if let Some(neigh) = adj.get(&u) {
            for (v, w) in neigh {
                let nd = du + *w as u64;
                if nd < *dist.get(v).unwrap_or(&u64::MAX) {
                    *dist.entry(v.clone()).or_insert(u64::MAX) = nd;
                }
            }
        }
    }

    let mut sorted_nodes = nodes;
    sorted_nodes.sort();
    println!("=== Shortest Paths from A ===");
    println!("");
    for n in sorted_nodes {
        let d = dist.get(&n).copied().unwrap_or(u64::MAX);
        if d == u64::MAX {
            println!("A -> {}: inf", n);
        } else {
            println!("A -> {}: {}", n, d);
        }
    }
}

